INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5801, 'Joshua 15:61', 'Joshua', 15, 61, '&nbsp;په صحرا کښې بيت‌اراباه، مدين، سکاکه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5802, 'Joshua 15:62', 'Joshua', 15, 62, '&nbsp;نِبسان، د مالګې ښار، او عين‌جدى وُو، شپږ ښارونه چې ګېرچاپېره ترې نه کلى هم وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5803, 'Joshua 15:63', 'Joshua', 15, 63, '&nbsp;خو د يهوداه خلق د دې قابل نۀ وُو چې هغه يبوسيان وشړى کوم يبوسيان چې په يروشلم کښې اوسېدل. يبوسيان تر اوسه پورې هلته د يهوداه د خلقو سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5804, 'Joshua 16:1', 'Joshua', 16, 1, '&nbsp;د يوسف اولاد ته چې کوم مُلک حواله شوے وو د هغې جنوبى سرحد د يريحو سره نزدې د اُردن نه شروع شوے وو، دا هغه ځائ وو چې د يريحو چينو نمرخاتۀ طرف ته وو او صحرا ته تلے وو. دا د يريحو نه تلے وو او تر بيت‌ايل پورې د غرونو مُلک ته ننوتلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5805, 'Joshua 16:2', 'Joshua', 16, 2, '&nbsp;د بيت‌ايل نه دا لوز ته تلے وو او عطارات ادار ته رسېدلے وو، چرته چې ارکيان اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5806, 'Joshua 16:3', 'Joshua', 16, 3, '&nbsp;بيا دا د لاندينى بيت‌حورون پورې، نمرپرېواتۀ طرف ته د يفليطيانو علاقې ته تلے وو. دا د هغه ځائ نه جزر ته تلے وو او د مديترانى په سمندر باندې ختم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5807, 'Joshua 16:4', 'Joshua', 16, 4, '&nbsp;دا زمکه د يوسف اولاد، د اِفرائيم قبيلو او د نمرپرېواتۀ طرف ته منسى ته مِلاو شوه چې د هغوئ خپل ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5808, 'Joshua 16:5', 'Joshua', 16, 5, '&nbsp;دا د اِفرائيم د قبيلې د کورَنو علاقه وه، د هغوئ سرحد نمرخاتۀ طرف ته د عطارات ادار نه پاسنى بيت‌حورون ته تلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5809, 'Joshua 16:6', 'Joshua', 16, 6, '&nbsp;او د هغه ځائ نه د مديترانى سمندر ته تلے وو. مکمتاه د هغوئ په شمالى طرف باندې وو. هلته نمرخاتۀ طرف ته سرحد د تانت سيلا طرف ته تاو وو او د ينوحاه نمرخاتۀ طرف ته تلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5810, 'Joshua 16:7', 'Joshua', 16, 7, '&nbsp;بيا دا د ينوحاه نه لاندې عطارات او نعراه ته تلے وو، چې يريحو ته رسېدلے وو او د اُردن سره ختم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5811, 'Joshua 16:8', 'Joshua', 16, 8, '&nbsp;نمرپرېواتۀ طرف ته سرحد د تفوح نه د قاناه نِهر ته تلے وو او د مديترانى سمندر سره ختم وو. دا هغه مُلک وو چې د اِفرائيم د قبيلې کورَنو ته ورکړے شوے وو چې د هغوئ ميراث شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5812, 'Joshua 16:9', 'Joshua', 16, 9, '&nbsp;چې په کښې يو څو هغه واړۀ ښارونه او کلى هم شامل وُو کوم چې د منسى په سرحدونو کښې دننه وُو، خو د اِفرائيم قبيلې له ورکړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5813, 'Joshua 16:10', 'Joshua', 16, 10, '&nbsp;خو هغوئ هغه کنعانيان ونۀ شړل کوم چې په جزر کښې اوسېدل، نو په دې وجه کنعانيان تر اوسه پورې د اِفرائيميانو سره اوسيږى، خو د کنعانيانو نه يې په زور کار اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5814, 'Joshua 17:1', 'Joshua', 17, 1, '&nbsp;د نمرپرېواتۀ طرف ته د اُردن يوه برخه د يوسف مشر زوئ منسى اولاد څۀ کورَنو ته مِلاو شوې وه. د جِلعاد پلار مکير، چې د منسى مشر زوئ وو هغه يو تکړه فوجى وو، نو په دې وجه جِلعاد او د نمرخاتۀ طرف ته بسن هغۀ ته حواله شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5815, 'Joshua 17:2', 'Joshua', 17, 2, '&nbsp;د اُردن نمرپرېواتۀ طرف ته زمکه د منسى دې باقى پاتې کورَنو ته حواله شوې وه يعنې ابيعزر، حالق، اسرى‌اېل، شِکم، حِفر او سميدع. دا د يوسف زوئ منسى نران اولاد وو او هغوئ د خپلو کورَنو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5816, 'Joshua 17:3', 'Joshua', 17, 3, '&nbsp;د حِفر زوئ صِلافحاد، چې دې زوئ د جِلعاد، جِلعاد زوئ د مکير او مکير زوئ د منسى وو، د صِلافحاد زامن نۀ وُو، خو صِرف لوڼه يې وې. د هغوئ نومونه محلاه، نوعاه، حجلاه، مِلکاه او تِرضاه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5817, 'Joshua 17:4', 'Joshua', 17, 4, '&nbsp;هغوئ اِلى‌عزر اِمام، د نون زوئ يشوَع او مشرانو له لاړې او ورته يې ووئيل، ”مالِک خُدائ موسىٰ له حُکم ورکړو چې مونږ له او داسې زمونږ نرانو خپلوانو له هم د زمکې يوه برخه راکړى چې زمونږ ميراث شى.“ نو چې څنګه مالِک خُدائ حُکم کړے وو هغۀ ورله د ترونو سره ميراث ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5818, 'Joshua 17:5', 'Joshua', 17, 5, '&nbsp;نو په دې وجه منسى ته د اُردن نمرخاتۀ طرف د جِلعاد او بسن نه علاوه لس نورې برخې مِلاو شوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5819, 'Joshua 17:6', 'Joshua', 17, 6, '&nbsp;ځکه چې د منسى قبيلې لوڼو ته د خپلو زامنو سره ميراث مِلاو شو. نو په دې وجه د جِلعاد مُلک د منسى د باقى پاتې اولاد ميراث شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5820, 'Joshua 17:7', 'Joshua', 17, 7, '&nbsp;د منسى علاقه د آشر نه د شِکم نمرخاتۀ طرف ته تر مکمتاه پورې ورسېده. بيا هغه سرحد د جنوب طرف ته لاړو چې په دې کښې د تفوح خلق شامل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5821, 'Joshua 17:8', 'Joshua', 17, 8, '&nbsp;د تفوح نه ګېرچاپېره علاقه د منسى وه، خو په سرحد باندې د تفوح ښار، د اِفرائيم د اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5822, 'Joshua 17:9', 'Joshua', 17, 9, '&nbsp;بيا سرحد لاندې د قاناه نِهر ته تلے وو. د نِهر جنوبى طرف ته ښارونه د اِفرائيم وُو، اګر چې دا د منسى په علاقه کښې وُو. د منسى سرحد د نِهر شمالى غاړې سره تلے وو او د مديترانى سمندر سره ختم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5823, 'Joshua 17:10', 'Joshua', 17, 10, '&nbsp;اِفرائيم جنوب طرف ته وو او منسى د شمال طرف ته وو او د نمرپرېواتۀ سرحد يې د مديترانى سمندر وو. آشر شمالى نمرپرېواتۀ طرف ته وو او يساکار شمالى نمرخاتۀ طرف ته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5824, 'Joshua 17:11', 'Joshua', 17, 11, '&nbsp;د يساکار او آشر په علاقو کښې، بيت‌شان او ابليعام د منسى وُو او تر دور پورې چې د سمندر په غاړه دے او د هغې نه ګېرچاپېره ښارونه هم د منسى وُو، عين دور، تعنک، مِجدو او د دې نه ګېرچاپېره ښارونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5825, 'Joshua 17:12', 'Joshua', 17, 12, '&nbsp;د منسى خلقو په دې ښارونو کښې اوسېدونکى خلق نۀ شول شړلے، نو په دې وجه کنعانيان هلته په زور اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5826, 'Joshua 17:13', 'Joshua', 17, 13, '&nbsp;اګر چې کله بنى اِسرائيليان تکړه هم شول، نو هغوئ بيا هم ټول کنعانيان ونۀ شړل، خو کنعانيان يې دې ته مجبور کړل چې په زبردستۍ ترې نه کار واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5827, 'Joshua 17:14', 'Joshua', 17, 14, '&nbsp;د يوسف اولاد يشوَع ته ووئيل، ”تا مونږ له د مُلک صِرف يوه برخه ولې راکړې ده چې زمونږ ميراث شى؟ مونږ ډېر زيات خلق يُو ځکه چې مالِک خُدائ مونږ له برکت راکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5828, 'Joshua 17:15', 'Joshua', 17, 15, '&nbsp;يشوَع ورته وفرمائيل، ”کۀ تاسو ډېر زيات يئ او د اِفرائيم د غرونو مُلک ستاسو دپاره کافى نۀ وى، نو بيا ځنګلو ته لاړ شئ او د فرزيانو او رفائيم په مُلک کښې د خپلو ځانونو دپاره زمکه صفا کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5829, 'Joshua 17:16', 'Joshua', 17, 16, '&nbsp;د يوسف قبيلې ورته ووئيل، ”د غرونو مُلک هم زمونږ دپاره کافى نۀ دے، او د مېدانونو او د بيت‌شان او د دې نه ګېرچاپېره ښارونو او د يزرعيل په وادۍ کښې اوسېدونکى ټول کنعانيان د اوسپنې جنګى ګاډۍ لرى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5830, 'Joshua 17:17', 'Joshua', 17, 17, '&nbsp;نو يشوَع د اِفرائيم او د نمرپرېواتۀ طرف ته منسى قبيلو ته ووئيل چې، ”په حقيقت کښې تاسو ډېر زيات يئ او تاسو ډېر تکړه شوى يئ. تاسو ته به د يوې برخې نه زياتې برخې ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5831, 'Joshua 17:18', 'Joshua', 17, 18, '&nbsp;د غرونو مُلک به ستاسو شى، اګر چې دا يو ځنګل دے، تاسو به دا صفا کړئ او د يو سر نه تر بل سَره پورې به يې ونيسئ. کۀ کنعانيان هر څومره تکړه هم وى او ورسره د اوسپنې جنګى ګاډۍ وى خو تاسو به بيا هم هغوئ وشړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5832, 'Joshua 18:1', 'Joshua', 18, 1, '&nbsp;کله چې هغوئ هغه مُلک فتح کړو نو د هغې نه پس، د بنى اِسرائيلو ټول قوم په سيلا کښې راغونډ شو او د مالِک خُدائ د حضور مقدسه خېمه يې ودروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5833, 'Joshua 18:2', 'Joshua', 18, 2, '&nbsp;د بنى اِسرائيلو اووۀ قبيلې تر اوسه پورې داسې وې چې هغوئ ته په هغه مُلک کښې حِصه نۀ وه حواله شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5834, 'Joshua 18:3', 'Joshua', 18, 3, '&nbsp;نو يشوَع بنى اِسرائيلو ته وفرمائيل، ”تاسو به ترڅو پورې دومره اِنتظار کوئ چې تاسو لاړ شئ او هغه مُلک ونيسئ کوم چې مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک تاسو له درکړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5835, 'Joshua 18:4', 'Joshua', 18, 4, '&nbsp;تاسو به د هرې قبيلې نه درې سړى خوښ کړئ او زۀ به هغوئ ولېږم چې هغه ټوله علاقه وګورى او د دې ميراث د تقسيمولو تفصيل راوړى او بيا به هغوئ ما له واپس راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5836, 'Joshua 18:5', 'Joshua', 18, 5, '&nbsp;هغه مُلک به په هغوئ باندې په اوو برخو کښې تقسيم شى، يهوداه به د هغې په جنوبى حِصه کښې ايسار شى او يوسف به د هغې په شمالى حِصه کښې ايسار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5837, 'Joshua 18:6', 'Joshua', 18, 6, '&nbsp;د دې اوو حِصو د تقسيم يو تفصيل وليکئ او ما له يې راوړئ. بيا به زۀ ستاسو دپاره د مالِک خُدائ ستاسو د خُدائ پاک په وړاندې د مشورې دپاره ستاسو سره پچه واچوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5838, 'Joshua 18:7', 'Joshua', 18, 7, '&nbsp;خو ليويانو ته به ستاسو نورو قبيلو سره د زمکې ميراث نۀ ملاويږى، ځکه چې د هغوئ برخه دا ده چې د مالِک خُدائ د اِمامانو په توګه خِدمت وکړى. او د جاد، روبين او د منسى قبيلو ته به نوره زمکه نۀ ملاويږى ځکه چې د مخکښې نه هغوئ ته خپله زمکه د اُردن نمرخاتۀ طرف ته مِلاو شوې ده، کومه چې د مالِک خُدائ خِدمت کوونکى موسىٰ هغوئ له ورکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5839, 'Joshua 18:8', 'Joshua', 18, 8, '&nbsp;کله چې هغه سړى د مُلک کتلو دپاره روان شول نو يشوَع ورته وفرمائيل چې، ”داسې به وکړئ، په هغه ټول مُلک باندې وګرځئ او تفصيل يې جوړ کړئ او بيا ما له واپس راشئ. او بيا به زۀ دلته په سيلا کښې د مالِک خُدائ په وړاندې د مشورې دپاره تاسو سره پچه واچوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5840, 'Joshua 18:9', 'Joshua', 18, 9, '&nbsp;نو هغه سړى په ټول مُلک باندې وګرځېدل او هغوئ د دې بيان وليکلو چې په اوو حِصو کښې به يې څنګه تقسيموى او د ښارونو تفصيل يې وليکلو. بيا هغوئ واپس يشوَع له د سيلا کېمپ ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5841, 'Joshua 18:10', 'Joshua', 18, 10, '&nbsp;نو يشوَع د هغوئ دپاره په سيلا کښې پچه واچوله چې د مالِک خُدائ سره مشوره وکړى او د بنى اِسرائيلو هرې پاتې شوې قبيلې ته يې د زمکې خپله خپله برخه حواله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5842, 'Joshua 18:11', 'Joshua', 18, 11, '&nbsp;اول پچه د بنيامين د قبيلې راوتله. د هغوئ زمکه د يهوداه او يوسف قبيلو په مينځ کښې پرته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5843, 'Joshua 18:12', 'Joshua', 18, 12, '&nbsp;په شمال کښې د هغوئ سرحد د اُردن سره شروع کېدو او بيا د يريحو شمال طرف ته بره ختلے وو او نمر پرېواتۀ طرف ته د بيت‌آون په صحرا کښې د غرونو په مُلک کښې تلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5844, 'Joshua 18:13', 'Joshua', 18, 13, '&nbsp;هغه سرحد بيا بره د لوز جنوبى طرف ته تلے وو چې د دې بيت‌ايل نوم هم وو، بيا عطارات ادار ته کوز شوے وو چې د بيت‌حورون په جنوب طرف په غر باندې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
