(5848, 'Joshua 18:17', 'Joshua', 18, 17, '&nbsp;بيا دا د عين‌شمس شمالى طرف ته او بيا جليلوت ته تاو وو، چې د ادميم درې ته مخامخ دے. سرحد بيا لاندې د بوهن کاڼى ته تلے وو، بوهن د روبين زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
