(5900, 'Joshua 19:41', 'Joshua', 19, 41, '&nbsp;په هغې کښې دا علاقې شاملې وې، صُرعا، اِستال، عيرشمس،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');